$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
$root=(Get-Location).Path
if(-not(Test-Path(Join-Path $root 'pubspec.yaml'))){throw 'Run this script from the almustafa-connect-erp project root.'}
$utf8=New-Object System.Text.UTF8Encoding($false)
$stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot=Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/parent_portal_phase4_$stamp"

function Read-ProjectFile([string]$p){
  $f=Join-Path $root $p
  if(-not(Test-Path $f)){throw "Required file not found: $p"}
  [IO.File]::ReadAllText($f).Replace("`r`n","`n")
}
function Write-ProjectFile([string]$p,[string]$c){
  $f=Join-Path $root $p
  New-Item -ItemType Directory -Path(Split-Path $f -Parent)-Force|Out-Null
  [IO.File]::WriteAllText($f,$c,$utf8)
  Write-Host "Created/updated: $p" -ForegroundColor Green
}
function Backup-ProjectFile([string]$p){
  $s=Join-Path $root $p
  if(-not(Test-Path $s)){return}
  $d=Join-Path $backupRoot $p
  New-Item -ItemType Directory -Path(Split-Path $d -Parent)-Force|Out-Null
  Copy-Item $s $d -Force
}
function Add-Import([string]$c,[string]$line){
  if($c.Contains($line)){return $c}
  $m=[regex]::Matches($c,"(?m)^import\s+['""].+?['""];\s*$")
  if($m.Count-eq 0){throw "Import block not found: $line"}
  $x=$m[$m.Count-1]
  $c.Insert($x.Index+$x.Length,"`n$line")
}
function Insert-BeforeFirst([string]$c,[string]$marker,[string[]]$patterns,[string]$block){
  if($c.Contains($marker)){return $c}
  foreach($p in $patterns){
    $m=[regex]::Match($c,$p)
    if($m.Success){return $c.Insert($m.Index,$block)}
  }
  throw "Registration anchor not found: $marker"
}

$payloads=@{
'lib/features/parent_portal/domain/entities/parent_notification_entity.dart'=''
'lib/features/parent_portal/data/models/parent_notification_model.dart'=''
'lib/features/parent_portal/domain/repositories/parent_notification_repository.dart'=''
'lib/features/parent_portal/data/repositories/parent_notification_repository_impl.dart'=''
'lib/features/parent_portal/domain/entities/parent_timeline_item_entity.dart'=''
'lib/features/parent_portal/domain/services/parent_timeline_service.dart'=''
'lib/features/parent_portal/data/services/parent_timeline_service_impl.dart'=''
'lib/features/parent_portal/presentation/bloc/parent_notification_bloc.dart'=''
'lib/features/parent_portal/presentation/pages/parent_notification_center_page.dart'=''
'lib/features/parent_portal/presentation/pages/parent_timeline_page.dart'=''
}
$paths='lib/core/constants/firestore_paths.dart'
$sl='lib/core/di/service_locator.dart'
$dashboard='lib/features/parent_portal/presentation/pages/parent_portal_dashboard_page.dart'

foreach($p in @($paths,$sl,$dashboard)+$payloads.Keys){Backup-ProjectFile $p}
foreach($item in $payloads.GetEnumerator()){
  $text=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($item.Value))
  Write-ProjectFile $item.Key $text
}

$c=Read-ProjectFile $paths
if(-not$c.Contains('parentNotifications')){
  $i=$c.LastIndexOf('}')
  if($i-lt 0){throw 'FirestorePaths closing brace not found.'}
  $c=$c.Insert($i,"  static const String parentNotifications = 'parent_notifications';`n")
}
Write-ProjectFile $paths $c

$c=Read-ProjectFile $sl
foreach($line in @(
"import '../../features/parent_portal/data/repositories/parent_notification_repository_impl.dart';",
"import '../../features/parent_portal/domain/repositories/parent_notification_repository.dart';",
"import '../../features/parent_portal/data/services/parent_timeline_service_impl.dart';",
"import '../../features/parent_portal/domain/services/parent_timeline_service.dart';",
"import '../../features/parent_portal/presentation/bloc/parent_notification_bloc.dart';"
)){
  $c=Add-Import $c $line
}

$regs=@'
  sl.registerLazySingleton<ParentNotificationRepository>(
    () => ParentNotificationRepositoryImpl(
      sl<FirebaseFirestoreService>(),
    ),
  );

  sl.registerLazySingleton<ParentTimelineService>(
    () => ParentTimelineServiceImpl(
      sl<FirebaseFirestore>(),
    ),
  );

'@
$c=Insert-BeforeFirst $c 'registerLazySingleton<ParentNotificationRepository>' @(
'(?m)^\s*sl\.registerLazySingleton<ParentCommunicationService>',
'(?m)^\s*sl\.registerLazySingleton<ParentAcademicService>',
'(?m)^\s*sl\.registerLazySingleton<'
) $regs

$bloc=@'
  sl.registerFactory<ParentNotificationBloc>(
    () => ParentNotificationBloc(
      sl<ParentNotificationRepository>(),
    ),
  );

'@
$c=Insert-BeforeFirst $c 'registerFactory<ParentNotificationBloc>' @(
'(?m)^\s*sl\.registerFactory<ParentCommunicationBloc>',
'(?m)^\s*sl\.registerFactory<ParentAcademicBloc>',
'(?m)^\s*sl\.registerFactory<'
) $bloc
Write-ProjectFile $sl $c

$c=Read-ProjectFile $dashboard
$c=Add-Import $c "import 'parent_notification_center_page.dart';"
$c=Add-Import $c "import 'parent_timeline_page.dart';"

if(-not$c.Contains('ParentNotificationCenterPage(')){
  $anchor="      appBar: AppBar(title: const Text('Parent Portal')),"
  $replacement=@'
      appBar: AppBar(
        title: const Text('Parent Portal'),
        actions: [
          if (loaded.selectedParent != null)
            IconButton(
              tooltip: 'Notifications',
              onPressed: () {
                Navigator.of(context).push<void>(
                  MaterialPageRoute<void>(
                    builder: (_) => ParentNotificationCenterPage(
                      parent: loaded.selectedParent!,
                      studentId: loaded.linkedStudents.isEmpty
                          ? null
                          : loaded.linkedStudents.first.id,
                    ),
                  ),
                );
              },
              icon: const Icon(Icons.notifications_outlined),
            ),
        ],
      ),
'@
  if($c.Contains($anchor)){
    $c=$c.Replace($anchor,$replacement)
  }else{
    Write-Host 'Parent Portal AppBar anchor not found; notification button will be added to student dashboard instead.' -ForegroundColor Yellow
  }
}

$oldModules="      ('Medical Alert', Icons.medical_information_outlined),"
if($c.Contains($oldModules)-and-not$c.Contains("('Timeline', Icons.timeline)")){
  $c=$c.Replace($oldModules,"      ('Timeline', Icons.timeline),`n$oldModules")
}

if(-not$c.Contains('ParentTimelinePage(')){
  $fallback="                  ScaffoldMessenger.of(context).showSnackBar("
  $idx=$c.LastIndexOf($fallback)
  if($idx-lt 0){throw 'Parent module fallback action not found.'}
  $insert=@'
                  if (module.$1 == 'Timeline') {
                    Navigator.of(context).push<void>(
                      MaterialPageRoute<void>(
                        builder: (_) => ParentTimelinePage(
                          parent: parent,
                          student: student,
                        ),
                      ),
                    );
                    return;
                  }

'@
  $c=$c.Insert($idx,$insert)
}
Write-ProjectFile $dashboard $c

Write-Host "`nRunning dart format..." -ForegroundColor Cyan
& dart format $paths $sl $dashboard 'lib/features/parent_portal'
if($LASTEXITCODE-ne 0){throw 'dart format failed.'}

Write-Host "`nRunning flutter analyze..." -ForegroundColor Cyan
& flutter analyze
if($LASTEXITCODE-ne 0){throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'}

Write-Host "`nParent Portal Phase 4 Notifications and Timeline completed successfully." -ForegroundColor Green
Write-Host 'Parent Portal is ready for final QA and freeze.' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
